import gurobipy
from gurobipy import GRB

def get_table_by_id(table_id):
    for tbl in CSVQA_DATA['tables']:
        if tbl.get('table_id') == table_id:
            return tbl
    raise ValueError(f"Table with id '{table_id}' not found in CSVQA_DATA")

def solve_problem():
    t_table = get_table_by_id('file_0_view_0')
    p_table = get_table_by_id('file_1_view_0')
    h_table = get_table_by_id('file_2_view_0')
    t = {}
    components = set()
    for rec in t_table['records']:
        values = rec['values']
        workshop = values['Unnamed: 0']
        for col, val in values.items():
            if col == 'Unnamed: 0':
                continue
            comp = col
            components.add(comp)
            try:
                t[workshop, comp] = float(val)
            except ValueError:
                raise ValueError(f'Invalid numeric value for t[{workshop},{comp}]: {val}')
    p = {}
    for rec in p_table['records']:
        values = rec['values']
        comp = values['Unnamed: 0']
        try:
            p[comp] = float(values['unit_price'])
        except ValueError:
            raise ValueError(f"Invalid numeric value for price of {comp}: {values['unit_price']}")
    H = {}
    for rec in h_table['records']:
        values = rec['values']
        workshop = values['workshop']
        try:
            H[workshop] = float(values['total_hours'])
        except ValueError:
            raise ValueError(f"Invalid numeric value for total_hours of {workshop}: {values['total_hours']}")
    missing_prices = components - p.keys()
    if missing_prices:
        raise ValueError(f'Missing unit prices for components: {sorted(missing_prices)}')
    missing_workshops = set(H.keys()) - {rec['values']['Unnamed: 0'] for rec in t_table['records']}
    if missing_workshops:
        raise ValueError(f'Workshop capacities provided for unknown workshops: {sorted(missing_workshops)}')
    m = gurobipy.Model('ComponentProduction')
    m.setParam('MIPGap', 1e-06)
    x = m.addVars(components, lb=0, vtype=GRB.CONTINUOUS, name='')
    m.setObjective(gurobipy.quicksum((p[c] * x[c] for c in components)), GRB.MAXIMIZE)
    for w, cap in H.items():
        expr = gurobipy.quicksum((t[w, c] * x[c] for c in components))
        m.addConstr(expr <= cap, name=f'Hours_{w}')
    m.optimize()
    return m
m = solve_problem()
